#!/usr/bin/env bash
# Question 3: ${Q3_APP} unreachable through the ingress. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl get ingressclass traefik >/dev/null 2>&1 && kubectl get gatewayclass traefik >/dev/null 2>&1 || {
  echo "this cluster image has no Traefik or Gateway API: rebuild images with ./cka images build --force" >&2
  exit 1
}
kubectl create namespace "${Q3_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q3_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q3_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl apply -f - <<EOF
apiVersion: apps/v1
kind: Deployment
metadata:
  name: ${Q3_APP}
  namespace: ${Q3_NS}
spec:
  replicas: 2
  selector:
    matchLabels: { app: ${Q3_APP} }
  template:
    metadata:
      labels: { app: ${Q3_APP} }
    spec:
      containers:
        - name: web
          image: nginx:1.27-alpine
          ports: [{ name: http, containerPort: 80 }]
          readinessProbe:
            httpGet: { path: /, port: http }
            periodSeconds: 5
---
apiVersion: v1
kind: Service
metadata:
  name: ${Q3_APP}
  namespace: ${Q3_NS}
spec:
  selector: { app: ${Q3_APP} }
  ports: [{ port: 80, targetPort: http }]
---
apiVersion: networking.k8s.io/v1
kind: Ingress
metadata:
  name: ${Q3_APP}
  namespace: ${Q3_NS}
spec:
  ingressClassName: traefik
  rules:
    - host: www.${Q3_NS}.lab
      http:
        paths:
          - path: /
            pathType: Prefix
            backend:
              service: { name: ${Q3_APP}, port: { number: 80 } }
---
apiVersion: gateway.networking.k8s.io/v1
kind: HTTPRoute
metadata:
  name: ${Q3_APP}
  namespace: ${Q3_NS}
spec:
  parentRefs:
    - { name: traefik-gateway, namespace: traefik, sectionName: web }
  hostnames: [api.${Q3_NS}.lab]
  rules:
    - backendRefs:
        - { name: ${Q3_APP}, port: 80 }
EOF
kubectl -n "${Q3_NS}" rollout status "deployment/${Q3_APP}" --timeout=240s
for _ in $(seq 1 60); do curl -s -m 5 -H "Host: www.${Q3_NS}.lab" http://controlplane:30080/ | grep -q 'Welcome to nginx' && break; sleep 2; done
curl -s -m 5 -H "Host: www.${Q3_NS}.lab" http://controlplane:30080/ | grep -q 'Welcome to nginx'
for _ in $(seq 1 60); do curl -s -m 5 -H "Host: api.${Q3_NS}.lab" http://controlplane:30080/ | grep -q 'Welcome to nginx' && break; sleep 2; done
curl -s -m 5 -H "Host: api.${Q3_NS}.lab" http://controlplane:30080/ | grep -q 'Welcome to nginx'

(
case "${Q3_FAULT}" in
  route-parent)
    kubectl -n "${Q3_NS}" patch httproute "${Q3_APP}" --type=json -p '[{"op":"replace","path":"/spec/parentRefs/0/name","value":"web-gateway"}]'
    ;;
  route-section)
    kubectl -n "${Q3_NS}" patch httproute "${Q3_APP}" --type=json -p '[{"op":"replace","path":"/spec/parentRefs/0/sectionName","value":"websecure"}]'
    ;;
  route-backend-port)
    kubectl -n "${Q3_NS}" patch httproute "${Q3_APP}" --type=json -p '[{"op":"replace","path":"/spec/rules/0/backendRefs/0/port","value":8080}]'
    ;;
  route-parent-namespace)
    kubectl -n "${Q3_NS}" patch httproute "${Q3_APP}" --type=json -p '[{"op":"remove","path":"/spec/parentRefs/0/namespace"}]'
    ;;
  route-backend-name)
    kubectl -n "${Q3_NS}" patch httproute "${Q3_APP}" --type=json -p '[{"op":"replace","path":"/spec/rules/0/backendRefs/0/name","value":"'"${Q3_APP}"'-svc"}]'
    ;;
  route-path-prefix)
    kubectl -n "${Q3_NS}" patch httproute "${Q3_APP}" --type=json -p '[{"op":"add","path":"/spec/rules/0/matches","value":[{"path":{"type":"PathPrefix","value":"/api"}}]}]'
    ;;
  route-weight-zero)
    kubectl -n "${Q3_NS}" patch httproute "${Q3_APP}" --type=json -p '[{"op":"add","path":"/spec/rules/0/backendRefs/0/weight","value":0}]'
    ;;
  route-filter-redirect)
    kubectl -n "${Q3_NS}" patch httproute "${Q3_APP}" --type=json -p '[{"op":"add","path":"/spec/rules/0/filters","value":[{"type":"RequestRedirect","requestRedirect":{"statusCode":302,"hostname":"elsewhere.example"}}]}]'
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac
)

(
case "${Q3_FAULT_2}" in
  controller-down)
    kubectl -n traefik scale deployment traefik --replicas=0
    kubectl -n traefik wait --for=delete pod -l app.kubernetes.io/name=traefik --timeout=120s >/dev/null 2>&1 || true
    ;;
  controller-nodeport)
    i=$(kubectl -n traefik get service traefik -o jsonpath='{range .spec.ports[*]}{.name}{"\n"}{end}' | grep -n '^web$' | cut -d: -f1)
    [[ -n "$i" ]] || { echo "no web port on the traefik Service" >&2; exit 1; }
    kubectl -n traefik patch service traefik --type=json -p '[{"op":"replace","path":"/spec/ports/'"$((i - 1))"'/nodePort","value":30081}]'
    ;;
  ingressclass-controller)
    kubectl get ingressclass traefik -o json | python3 -c 'import json,sys; o=json.load(sys.stdin); m=o["metadata"]; [m.pop(k, None) for k in ("resourceVersion","uid","creationTimestamp","managedFields","generation")]; print(json.dumps(o))' > /var/tmp/cka-ingressclass-traefik.json
    python3 -c 'import json; o=json.load(open("/var/tmp/cka-ingressclass-traefik.json")); o["spec"]["controller"]="k8s.io/ingress-nginx"; print(json.dumps(o))' > /var/tmp/cka-ingressclass-broken.json
    kubectl delete ingressclass traefik --wait=true >/dev/null
    kubectl create -f /var/tmp/cka-ingressclass-broken.json >/dev/null
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac
)

(
case "${Q3_FAULT}" in
  route-parent)
    for _ in $(seq 1 45); do
      curl -s -m 5 -H "Host: api.${Q3_NS}.lab" http://controlplane:30080/ | grep -q 'Welcome to nginx' || exit 0
      sleep 2
    done
    echo "api.${Q3_NS}.lab is still served" >&2
    exit 1
    ;;
  route-section)
    for _ in $(seq 1 45); do
      curl -s -m 5 -H "Host: api.${Q3_NS}.lab" http://controlplane:30080/ | grep -q 'Welcome to nginx' || exit 0
      sleep 2
    done
    echo "api.${Q3_NS}.lab is still served" >&2
    exit 1
    ;;
  route-backend-port)
    for _ in $(seq 1 45); do
      curl -s -m 5 -H "Host: api.${Q3_NS}.lab" http://controlplane:30080/ | grep -q 'Welcome to nginx' || exit 0
      sleep 2
    done
    echo "api.${Q3_NS}.lab is still served" >&2
    exit 1
    ;;
  route-parent-namespace)
    for _ in $(seq 1 45); do
      curl -s -m 5 -H "Host: api.${Q3_NS}.lab" http://controlplane:30080/ | grep -q 'Welcome to nginx' || exit 0
      sleep 2
    done
    echo "api.${Q3_NS}.lab is still served" >&2
    exit 1
    ;;
  route-backend-name)
    for _ in $(seq 1 45); do
      curl -s -m 5 -H "Host: api.${Q3_NS}.lab" http://controlplane:30080/ | grep -q 'Welcome to nginx' || exit 0
      sleep 2
    done
    echo "api.${Q3_NS}.lab is still served" >&2
    exit 1
    ;;
  route-path-prefix)
    for _ in $(seq 1 45); do
      curl -s -m 5 -H "Host: api.${Q3_NS}.lab" http://controlplane:30080/ | grep -q 'Welcome to nginx' || exit 0
      sleep 2
    done
    echo "api.${Q3_NS}.lab is still served" >&2
    exit 1
    ;;
  route-weight-zero)
    for _ in $(seq 1 45); do
      curl -s -m 5 -H "Host: api.${Q3_NS}.lab" http://controlplane:30080/ | grep -q 'Welcome to nginx' || exit 0
      sleep 2
    done
    echo "api.${Q3_NS}.lab is still served" >&2
    exit 1
    ;;
  route-filter-redirect)
    for _ in $(seq 1 45); do
      curl -s -m 5 -H "Host: api.${Q3_NS}.lab" http://controlplane:30080/ | grep -q 'Welcome to nginx' || exit 0
      sleep 2
    done
    echo "api.${Q3_NS}.lab is still served" >&2
    exit 1
    ;;
esac
)

(
case "${Q3_FAULT_2}" in
  controller-down)
    for _ in $(seq 1 45); do
      curl -s -m 5 -H "Host: www.${Q3_NS}.lab" http://controlplane:30080/ | grep -q 'Welcome to nginx' || exit 0
      sleep 2
    done
    echo "www.${Q3_NS}.lab is still served" >&2
    exit 1
    ;;
  controller-nodeport)
    for _ in $(seq 1 45); do
      curl -s -m 5 -H "Host: www.${Q3_NS}.lab" http://controlplane:30080/ | grep -q 'Welcome to nginx' || exit 0
      sleep 2
    done
    echo "www.${Q3_NS}.lab is still served" >&2
    exit 1
    ;;
  ingressclass-controller)
    for _ in $(seq 1 45); do
      curl -s -m 5 -H "Host: www.${Q3_NS}.lab" http://controlplane:30080/ | grep -q 'Welcome to nginx' || exit 0
      sleep 2
    done
    echo "www.${Q3_NS}.lab is still served" >&2
    exit 1
    ;;
esac
)
